#!/usr/bin/env node
/**
 * Tests for workflows/impl-review-loop.js. Zero dependencies — `node:test` on Node 18+.
 *
 *   node --test "tools/*.test.mjs"
 *
 * Two layers. The round-decision logic is a pure block between `// --- pure:begin` and `// --- pure:end`;
 * the test extracts it and calls it directly. The whole script is then run the way the runtime runs a
 * workflow (the body of an async function) with a scripted `agent`, to see the loop end in OK or STALL
 * and a resume carry on past a stall.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

const SOURCE = readFileSync(join(dirname(fileURLToPath(import.meta.url)), '..', 'workflows', 'impl-review-loop.js'), 'utf8');
const pure = SOURCE.split('// --- pure:begin')[1].split('// --- pure:end')[0];
const { decideRound, mergeReviews, dedupeFound, inPerimeter, classify, parseDirty, sameFinding, groupFiles, groupOf, unreviewedFiles, reviewersFor, sizeFor, readReport, verifyGate, deltaCommand, isNeverBlocking, widenedFiles, rejectionLedger, cleanupCandidates, readAnswers, findingHistory, churnGrowing, coverageAction, coverageOwners, recheckReviewers, idsToAsk } =
  new Function(`${pure}\nreturn { decideRound, mergeReviews, dedupeFound, inPerimeter, classify, parseDirty, sameFinding, groupFiles, groupOf, unreviewedFiles, reviewersFor, sizeFor, readReport, verifyGate, deltaCommand, isNeverBlocking, widenedFiles, rejectionLedger, cleanupCandidates, readAnswers, findingHistory, churnGrowing, coverageAction, coverageOwners, recheckReviewers, idsToAsk }`)();

const FILES = ['src/Orders/OrdersQuery.cs', 'src/Orders/Dto/', 'tests/**/Orders*.cs'];
const f = (id, extra = {}) => ({ id, path: 'src/Orders/OrdersQuery.cs', category: 'correctness', priority: 'P2', title: id, failure: 'x', ...extra });

const ROOT = 'C:/repo';

test('inPerimeter: file, directory, glob, absolute path under the root, case, anchored at the root', () => {
  assert.ok(inPerimeter('src/Orders/OrdersQuery.cs', FILES));
  assert.ok(inPerimeter('src\\Orders\\Dto\\A.cs', FILES));
  assert.ok(inPerimeter('tests/unit/deep/OrdersTests.cs', FILES));
  assert.ok(inPerimeter('C:/repo/src/orders/ordersquery.cs', FILES, ROOT));
  assert.ok(inPerimeter('c:\\Repo\\src\\Orders\\OrdersQuery.cs', FILES, ROOT));
  assert.ok(!inPerimeter('C:/other/src/Orders/OrdersQuery.cs', FILES, ROOT));
  assert.ok(!inPerimeter('other/src/Orders/OrdersQuery.cs', FILES, ROOT));
  assert.ok(!inPerimeter('src/Orders/OrdersController.cs', FILES));
  assert.ok(!inPerimeter('src/Other/src/Orders/OrdersQuery.cs.bak', FILES));
  assert.ok(!inPerimeter('', FILES));
});

test('classify: a scope finding blocks, a defect outside is "trovato altro", P3 inside is minor', () => {
  assert.equal(classify(f('a'), FILES), 'blocking');
  assert.equal(classify(f('a', { priority: 'P3' }), FILES), 'minor');
  assert.equal(classify(f('a', { path: 'src/Other.cs' }), FILES), 'outOfScope');
  assert.equal(classify(f('a', { path: 'src/Other.cs', category: 'scope', priority: 'P3' }), FILES), 'blocking');
});

test('round 1, new P1/P2 findings only → FIX, they are tracked open', () => {
  const d = decideRound({ found: [f('F1'), f('F2', { priority: 'P1' })], files: FILES });
  assert.equal(d.action, 'FIX');
  assert.deepEqual(d.toFix, ['F1', 'F2']);
  assert.equal(d.tracked.F1.status, 'open');
});

test('round 1 with nothing blocking → DONE, the rest is recorded apart', () => {
  const d = decideRound({ found: [f('F1', { priority: 'P3' }), f('F2', { path: 'src/Other.cs' })], files: FILES });
  assert.equal(d.action, 'DONE');
  assert.deepEqual(d.minor, ['F1']);
  assert.deepEqual(d.outOfScope, ['F2']);
});

test('only NEW findings after a fix, the old ones closed → continue (FIX)', () => {
  const d = decideRound({
    tracked: { F1: { status: 'open' } }, verdicts: { F1: 'closed' }, found: [f('F2')], files: FILES,
  });
  assert.equal(d.action, 'FIX');
  assert.deepEqual(d.closed, ['F1']);
  assert.deepEqual(d.toFix, ['F2']);
});

test('the same finding still open after a fix → STALL', () => {
  const d = decideRound({ tracked: { F1: { status: 'open' } }, verdicts: { F1: 'open' }, found: [f('F2')], files: FILES });
  assert.equal(d.action, 'STALL');
  assert.deepEqual(d.stalled, [{ id: 'F1', why: 'still-open' }]);
});

test('a finding closed earlier that is open again → STALL', () => {
  const d = decideRound({ tracked: { F1: { status: 'closed' } }, verdicts: { F1: 'open' }, files: FILES });
  assert.equal(d.action, 'STALL');
  assert.deepEqual(d.stalled, [{ id: 'F1', why: 'reappeared' }]);
});

test('all closed, nothing new → DONE', () => {
  const d = decideRound({ tracked: { F1: { status: 'open' }, F2: { status: 'closed' } }, verdicts: { F1: 'closed', F2: 'closed' }, files: FILES });
  assert.equal(d.action, 'DONE');
  assert.deepEqual(d.closed, ['F1']);
});

test('an open finding with no verdict is not a stall and never a pass: RECHECK, it stays open and is asked again', () => {
  const d = decideRound({ tracked: { F1: { status: 'open' } }, verdicts: {}, files: FILES });
  assert.equal(d.action, 'RECHECK');
  assert.deepEqual(d.unanswered, ['F1']);
  assert.equal(d.tracked.F1.status, 'open');
  assert.equal(decideRound({ tracked: { F1: { status: 'open' } }, verdicts: {}, found: [f('F2')], files: FILES }).action, 'FIX');
});

test('resolution: accept drops the stall; guidance sends the stalled finding back to the fixer', () => {
  const base = { tracked: { F1: { status: 'open' } }, verdicts: { F1: 'open' }, files: FILES };
  const accepted = decideRound({ ...base, resolution: { accept: ['F1'] } });
  assert.equal(accepted.action, 'DONE');
  assert.equal(accepted.tracked.F1.status, 'accepted');
  const guided = decideRound({ ...base, resolution: { guidance: 'use a join' } });
  assert.equal(guided.action, 'FIX');
  assert.deepEqual(guided.toFix, ['F1']);
  const retried = decideRound({ ...base, resolution: { retry: true } });
  assert.equal(retried.action, 'FIX');
  assert.deepEqual(retried.toFix, ['F1']);
});

