  const models = (round) => calls.filter((c) => c.opts.label?.startsWith(`R${round} `)).map((c) => `${c.opts.label}:${c.opts.model}:${c.opts.effort}`);
  assert.deepEqual(models(1), ['R1 A:sonnet:medium']);
