  assert.match(r1, /list the implementer declared \(src\/Orders\/OrdersQuery\.cs\) is a hint/);
  assert.match(r2, /DELTA of the last fix/);
  assert.match(r2, /Files the fix changed: src\/Orders\/Dto\/A\.cs/);
